/* bs-auditoria.sql — _BS_AUDITORIA_SUPA_V1 (07-nov-2026)
   Tablas de la copia completa de la hoja BS_Auditoria (Bienestar Social) en Supabase.
   Mismo patrón que las demás bs_* de esquema-supabase.sql (tabla + tabla de paso __carga).
   Uso: cd C:\sistema-rl-verfrut\migracion ; node aplicar-sql.js bs-auditoria.sql */
CREATE TABLE IF NOT EXISTS rl."bs_auditoria" (
  "id_fila" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "fila" integer NOT NULL,
  "fecha" timestamp,
  "usuario" extensions.citext,
  "accion" extensions.citext,
  "modulo" extensions.citext,
  "registro_id" extensions.citext,
  "detalle" extensions.citext,
  "otros" extensions.citext,
  "actualizado" timestamp DEFAULT (now() at time zone 'utc') NOT NULL,
  PRIMARY KEY ("id_fila")
);
CREATE UNIQUE INDEX IF NOT EXISTS "ix_bs_auditoria_ux_bs_auditoria_fila" ON rl."bs_auditoria" ("fila");
CREATE TABLE IF NOT EXISTS rl."bs_auditoria__carga" (
  "fila" integer NOT NULL,
  "fecha" timestamp,
  "usuario" extensions.citext,
  "accion" extensions.citext,
  "modulo" extensions.citext,
  "registro_id" extensions.citext,
  "detalle" extensions.citext,
  "otros" extensions.citext
);
